'haut-bailly|2005':{blend:{CS:58,ME:36,CF:6},url:'https://www.haut-bailly.com/millesime-2005-legendaire/',src:'2005__en-vintage-2005-legendary.txt'},
'haut-bailly|2007':{blend:{CS:70,ME:26,CF:4},url:'https://www.haut-bailly.com/millesime-2007-la-constance/',src:'2007__en-vintage-2007-regularity.txt'},
'haut-bailly|2009':{blend:{CS:60,ME:37,CF:3},url:'https://www.haut-bailly.com/millesime-2009-mythique/',src:'2009__en-vintage-2009-mythic.txt'},
'haut-bailly|2010':{blend:{CS:62,ME:36,CF:2},url:'https://www.haut-bailly.com/millesime-2010-lexcellence/',src:'2010__en-vintage-2010-excellence-2.txt'},
'haut-bailly|2011':{blend:{CS:50,ME:47,CF:3},url:'https://www.haut-bailly.com/millesime-2011-marque-du-sceau-de-son-terroir/',src:'2011__en-vintage-2011-stamped-with-the-seal-of-its-terroir.txt'},
