'la-mission-haut-brion|2002':{blend:{CS:48,ME:52},alc:13,src:'Fiche-technique_MissionHBR_2002_EN.pdf'},
'la-mission-haut-brion|2003':{blend:{CS:52,ME:39,CF:9},alc:13,src:'Fiche-technique_MissionHBR_2003_EN.pdf'},
